import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = list(map(int, input_data[1:n+1]))

    ans = [-1] * n

    q = deque()
    visited = [False] * n

    for i in range(n):
        p = a[i] % 2
        left = i - a[i]
        right = i + a[i]

        if left >= 0 and a[left] % 2 != p:
            ans[i] = 1
            continue
        if right < n and a[right] % 2 != p:
            ans[i] = 1

        if ans[i] != 1:
            q.append(i)
            visited[i] = True

    while q:
        curr = q.popleft()
        curr_parity = a[curr] % 2

        left = curr - a[curr]
        right = curr + a[curr]

        for nxt in [left, right]:
            if 0 <= nxt < n:
                if a[nxt] % 2 != curr_parity:
                    if ans[curr] == -1:
                        ans[curr] = ans[nxt] + 1
                    else:
                        ans[curr] = min(ans[curr], ans[nxt] + 1)
                else:
                    if not visited[nxt]:
                        visited[nxt] = True
                        q.append(nxt)

    print(*(ans))

if __name__ == "__main__":
    solve()
